// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/jetbrains-mono";
import "@fontsource/noto-sans-kr";

export const jetbrainsMono = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

type Progress = { line: number; char: number; done: boolean };

export type Typewriter = {
  /** Lines that have finished typing. */
  settled: string[];
  /** The line currently being typed ("" when idle or done). */
  typing: string;
  done: boolean;
  /** Complete the whole sequence instantly (skip). */
  finish: () => void;
};

export type TypewriterOptions = {
  /** Base delay per character tick, ms. */
  charMs?: number;
  /** Random extra delay per tick, ms. */
  jitterMs?: number;
  /** Pause between lines, ms. */
  linePauseMs?: number;
  /** Delay before the first character, ms. */
  startDelayMs?: number;
};

/**
 * A data-terminal typewriter for episode titles and feed log lines. While
 * `play` is false the text is fully "typed" — which is what the server
 * renders, so nothing is hidden without JS. Cadence is even but not
 * metronomic: a small jitter keeps it alive without pretending to be a UART
 * boot (this is an analytics terminal, not PALE.SIGNAL's cold boot).
 */
export function useTypewriter(
  lines: readonly string[],
  play: boolean,
  options?: TypewriterOptions,
): Typewriter {
  const charMs = options?.charMs ?? 32;
  const jitterMs = options?.jitterMs ?? 22;
  const linePauseMs = options?.linePauseMs ?? 220;
  const startDelayMs = options?.startDelayMs ?? 320;

  const [progress, setProgress] = useState<Progress>({
    line: lines.length,
    char: 0,
    done: true,
  });
  const [prevPlay, setPrevPlay] = useState(play);
  const timerRef = useRef(0);

  // Sanctioned render-time adjustment: rewind the tape the moment play flips
  // on, so the completed no-JS text never coexists with the typing state.
  if (prevPlay !== play) {
    setPrevPlay(play);
    if (play) setProgress({ line: 0, char: 0, done: false });
  }

  const finish = useCallback(() => {
    window.clearTimeout(timerRef.current);
    setProgress({ line: lines.length, char: 0, done: true });
  }, [lines.length]);

  useEffect(() => {
    if (!play) return;
    let line = 0;
    let char = 0;

    const step = () => {
      const current = lines[line] ?? "";
      if (char < current.length) {
        char += 1;
        setProgress({ line, char, done: false });
        timerRef.current = window.setTimeout(
          step,
          charMs + Math.random() * jitterMs,
        );
      } else if (line < lines.length - 1) {
        line += 1;
        char = 0;
        setProgress({ line, char, done: false });
        timerRef.current = window.setTimeout(step, linePauseMs);
      } else {
        setProgress({ line: lines.length, char: 0, done: true });
      }
    };

    timerRef.current = window.setTimeout(step, startDelayMs);
    return () => window.clearTimeout(timerRef.current);
  }, [play, lines, charMs, jitterMs, linePauseMs, startDelayMs]);

  const settled = lines.slice(0, progress.line);
  const typing = progress.done
    ? ""
    : (lines[progress.line] ?? "").slice(0, progress.char);

  return { settled, typing, done: progress.done, finish };
}

"use client";

import { useEffect, useRef, useState } from "react";
import "./styles.css";
import { jetbrainsMono, notoSansKR } from "./fonts";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useTypewriter } from "./hooks/useTypewriter";

/**
 * WAVE — a podcast/music-network analytics dashboard whose signature is a
 * live ASCII spectrum analyzer. Where PALE.SIGNAL is poetry/logs and GLITCH
 * is corruption, WAVE is data-visualization — a functional terminal dashboard
 * with a real equalizer in text. Calm, technical, beautiful data.
 *
 * `.wave-js` is added imperatively on mount: every pre-reveal style is gated
 * behind it, and with JavaScript off the dashboard simply stands finished.
 */
const BARS = 48;
const GLYPHS = "▁▂▃▄▅▆▇█";

export default function WavePage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const [spectrum, setSpectrum] = useState<number[]>(
    () => Array.from({ length: BARS }, () => 0.2),
  );
  // Peak-hold caps — the slow-decaying amber markers above each bar that make
  // the meter read as a real LED analyzer, not a single line of text-shadow.
  const [peaks, setPeaks] = useState<number[]>(
    () => Array.from({ length: BARS }, () => 0.2),
  );
  const peaksRef = useRef<number[]>(Array.from({ length: BARS }, () => 0.2));
  const raf = useRef(0);
  const phase = useRef(0);

  // The simulated audio beat — a few sine layers driving bar heights.
  useEffect(() => {
    rootRef.current?.classList.add("wave-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "wave" }, "*");

    if (reduced) return;
    const tick = () => {
      raf.current = requestAnimationFrame(tick);
      phase.current += 0.04;
      const t = phase.current;
      const next = Array.from({ length: BARS }, (_, i) => {
        const center = BARS / 2;
        const dist = Math.abs(i - center) / center;
        const env = Math.max(0.08, 1 - dist * 0.7);
        const beat =
          0.5 +
          0.3 * Math.sin(t * 2.0 + i * 0.3) +
          0.2 * Math.sin(t * 5.0 + i * 0.7);
        return Math.max(0.05, Math.min(1, beat * env));
      });
      setSpectrum(next);
      // Peak-hold: grab the new high, otherwise decay slowly. The 0.985 factor
      // + 0.001 floor gives a graceful LED-meter fall, ~1.5s from full.
      const nextPeaks = next.map((v, i) =>
        Math.max(peaksRef.current[i] * 0.985 - 0.001, v),
      );
      peaksRef.current = nextPeaks;
      setPeaks(nextPeaks);
    };
    raf.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf.current);
  }, [reduced]);

  const tagline = useTypewriter(
    ["◎ WAVE — 지금 재생 중: 새벽 녹음, EP.044"],
    !reduced,
  );
  const taglineText = tagline.settled[0] ?? tagline.typing ?? "";

  return (
    <div
      ref={rootRef}
      className={`${jetbrainsMono.variable} ${notoSansKR.variable} wave-root`}
    >
      <header className="wave-hero" data-reveal="">
        <p className="wave-kicker">
          <span lang="ko">오디오 네트워크 분석</span> · AUDIO NETWORK ANALYTICS
        </p>
        <h1 className="wave-title">
          WAVE <span lang="ko">파동</span>
        </h1>
        <p className="wave-tagline">{taglineText}</p>
      </header>

      <section className="wave-spectrum-section" aria-labelledby="wave-spec-title">
        <h2 id="wave-spec-title" className="wave-secthead" data-reveal="">
          <span lang="ko">스펙트럼</span> · spectrum
        </h2>
        {/* The SVG meter is the signature: real bars, real peak-hold caps,
            a phosphor→amber gradient so loud bands glow warm. Hidden from
            AT behind the labeled ASCII strip below. */}
        <div
          className="wave-spectrum"
          role="img"
          aria-hidden="true"
          data-reveal=""
        >
          <svg
            className="wave-spectrum__svg"
            viewBox="0 0 480 200"
            preserveAspectRatio="none"
          >
            <defs>
              {/* Vertical meter gradient: green bed → amber head, applied in
                  userSpaceOnUse so tall bars literally climb into the warm. */}
              <linearGradient id="wave-grad" x1="0" y1="200" x2="0" y2="0" gradientUnits="userSpaceOnUse">
                <stop offset="0" stopColor="#4ade80" />
                <stop offset="0.62" stopColor="#4ade80" />
                <stop offset="0.82" stopColor="#a3e635" />
                <stop offset="0.95" stopColor="#fbbf24" />
                <stop offset="1" stopColor="#fb923c" />
              </linearGradient>
            </defs>
            {spectrum.map((v, i) => {
              const gap = 2;
              const w = (480 - gap * (BARS - 1)) / BARS;
              const x = i * (w + gap);
              const h = Math.max(2, v * 200);
              const y = 200 - h;
              const pkY = 200 - Math.max(2, peaks[i] * 200) - 2;
              return (
                <g key={i}>
                  <rect
                    className="wave-spectrum__bar"
                    x={x}
                    y={y}
                    width={w}
                    height={h}
                  />
                  {/* Peak-hold cap — a thin amber tick that lingers at the
                      loudest recent level, then decays. */}
                  <rect
                    className="wave-spectrum__peak"
                    x={x}
                    y={pkY}
                    width={w}
                    height={2}
                  />
                </g>
              );
            })}
          </svg>
          {/* The ASCII channel keeps the original charm as a secondary strip. */}
          <pre className="wave-spectrum__ascii">
            {spectrum
              .map((v) => GLYPHS[Math.min(7, Math.floor(v * 8))])
              .join("")}
          </pre>
        </div>
        <p className="wave-spec-meta" data-reveal="">
          <span lang="ko">48 밴드 · 60fps · 시뮬레이션</span> · 48 bands · 60fps
          · simulated
        </p>
      </section>

      <section className="wave-stats" aria-labelledby="wave-stats-title">
        <h2 id="wave-stats-title" className="wave-secthead" data-reveal="">
          <span lang="ko">통계</span> · stats
        </h2>
        <dl className="wave-stat-grid">
          <div data-reveal="">
            <dt>listeners</dt>
            <dd>12,847</dd>
          </div>
          <div data-reveal="">
            <dt>peak</dt>
            <dd>21,304</dd>
          </div>
          <div data-reveal="">
            <dt>episodes</dt>
            <dd>044</dd>
          </div>
          <div data-reveal="">
            <dt>uptime</dt>
            <dd>99.98%</dd>
          </div>
        </dl>
      </section>

      <div className="wave-marquee" aria-hidden="true">
        <span className="wave-marquee__track">
          ◎ NOW PLAYING · <span lang="ko">새벽 녹음</span> EP.044 ·{" "}
          <span lang="ko">다음</span> EP.045 — <span lang="ko">비밀</span> ·
          WAVE.NETWORK · 2026 ·
        </span>
      </div>

      <footer className="wave-foot" data-reveal="">
        <p>
          © 2026 WAVE · <span lang="ko">오디오 네트워크</span> · MIT
        </p>
        <p>
          <span lang="ko">전부 코드로 그렸다 — 실제 오디오 없음.</span> drawn
          entirely in code — no real audio.
        </p>
      </footer>
    </div>
  );
}

/* ==========================================================================
   WAVE 파동 — audio network analytics · spectrum analyzer dashboard
   terminal-core · terminal black / phosphor green / amber / soft white
   Scoped by convention to .wave-root; classes prefixed wave-.

   Where GLITCH is corrupted signal and PALE.SIGNAL is poetry, WAVE is
   functional data — a calm broadcast desk. Every readout is tabular,
   every glow is a real 3-tier phosphor stack, and the spectrum is a true
   SVG meter with peak-hold caps, not a single line of text-shadow.
   ========================================================================== */

.wave-root {
  /* -- palette ---------------------------------------------------------- */
  /* All ratios measured against --wave-bg (#0a0e0a). */
  --wave-bg: #0a0e0a;          /* ground — the CRT phosphor well, before power */
  --wave-bg-deep: #060906;     /* recess — panel insets, the darker scan area */
  --wave-phosphor: #4ade80;    /* primary ink + spectrum — the live signal (11.2:1, AAA) */
  --wave-amber: #fbbf24;       /* tagline + focus + peaks — warm secondary (11.6:1, AAA) */
  --wave-soft: #e8f0e8;        /* display + stat values — paper-white (16.7:1, AAA) */
  --wave-dim: #6b806b;         /* kicker/tertiary — the operator muttering (4.56:1, AA) */
  --wave-hairline: rgba(74, 222, 128, 0.20);
                               /* decorative ONLY — rules, dividers (~1.4:1, no text) */

  /* -- type ------------------------------------------------------------- */
  --wave-font-mono: "JetBrains Mono", monospace;
  --wave-font-kr: "Noto Sans KR", sans-serif;
  /* Hangul falls through the mono face into Noto Sans KR */
  --wave-font-stack: "JetBrains Mono", "Noto Sans KR", monospace;

  /* -- spacing — 4px baseline, no magic numbers ------------------------- */
  --wave-s-1: 0.25rem;   /*  4px */
  --wave-s-2: 0.5rem;    /*  8px — grid unit */
  --wave-s-3: 0.75rem;   /* 12px */
  --wave-s-4: 1rem;      /* 16px */
  --wave-s-5: 1.25rem;   /* 20px */
  --wave-s-6: 1.5rem;    /* 24px */
  --wave-s-8: 2rem;      /* 32px */
  --wave-s-10: 2.5rem;   /* 40px */
  --wave-s-12: 3rem;     /* 48px */
  --wave-s-pad: clamp(24px, 6vw, 80px);   /* section gutter */
  --wave-s-pad-y: clamp(60px, 12vh, 120px);

  /* -- motion — easing split by purpose --------------------------------- */
  --wave-ease-enter: cubic-bezier(0.16, 1, 0.3, 1);   /* reveal — strong ease-out */
  --wave-ease-glow:  cubic-bezier(0.22, 1, 0.36, 1);  /* spectrum scrub — long tail */
  --wave-ease-state: cubic-bezier(0.34, 1.56, 0.64, 1); /* hover — micro bounce */
  --wave-reveal-ms: 700ms;

  /* -- phosphor glow stacks (terminal-core §3-tier) -------------------- */
  --wave-glow-phosphor:
    0 0 2px rgba(74, 222, 128, 0.90),
    0 0 8px rgba(74, 222, 128, 0.55),
    0 0 20px rgba(74, 222, 128, 0.30);
  --wave-glow-amber:
    0 0 2px rgba(251, 191, 36, 0.90),
    0 0 10px rgba(251, 191, 36, 0.45),
    0 0 24px rgba(251, 191, 36, 0.22);
  --wave-glow-soft:
    0 0 2px rgba(232, 240, 232, 0.55),
    0 0 14px rgba(74, 222, 128, 0.32),
    0 0 34px rgba(74, 222, 128, 0.16);

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--wave-bg);
  color: var(--wave-phosphor);
  font-family: var(--wave-font-stack);
  font-weight: 400;
  font-size: clamp(14px, 0.4vw + 12px, 16px);
  line-height: 1.7;
  font-variant-numeric: tabular-nums;   /* terminal readouts never jitter */
  text-wrap: pretty;
  overflow-x: hidden;
  overflow-x: clip;
}

/* ==========================================================================
   CRT atmosphere — phosphor bloom at screen center + scanline glass face.
   The scanline overlay sits above content but stays pointer-events-none and
   subtle enough that worst-case text contrast stays above AA.
   ========================================================================== */

.wave-root::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(
    100% 80% at 50% 40%,
    rgba(74, 222, 128, 0.06),
    transparent 60%
  );
}

.wave-root::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent 0 2px,
    rgba(0, 0, 0, 0.10) 2px 3px
  );
  opacity: 0.6;
}

/* Slow scanline crawl — 3px over 9s (~0.33Hz), well under the 3Hz photo-
   safety ceiling. Seamless because the gradient's period is 3px. */
.wave-root.wave-js::after {
  animation: wave-scan 9s linear infinite;
}

/* ==========================================================================
   Korean — first-class voice. Never nest :lang(ko) inside :lang(ko).
   Hangul needs more line-height and zero tracking.
   ========================================================================== */

.wave-root :lang(ko) {
  font-family: var(--wave-font-kr);
  letter-spacing: 0;
  line-height: 1.9;
  word-break: keep-all;
  word-wrap: break-word;
}

.wave-root ::selection {
  background: var(--wave-phosphor);
  color: var(--wave-bg);
  text-shadow: none;
}

/* Keyboard focus — amber ring with a phosphor halo, scoped to the entry. */
.wave-root :focus-visible {
  outline: 2px solid var(--wave-amber);
  outline-offset: 3px;
  border-radius: 1px;
  box-shadow:
    0 0 0 1px rgba(74, 222, 128, 0.40),
    0 0 14px rgba(251, 191, 36, 0.35);
}

/* ==========================================================================
   Reveal gating — entrance easing only. .wave-js is added on mount; without
   it the dashboard simply stands finished (no pre-hidden content).
   ========================================================================== */

.wave-js [data-reveal] {
  opacity: 0;
  transform: translateY(18px);
  transition:
    opacity var(--wave-reveal-ms) var(--wave-ease-enter),
    transform var(--wave-reveal-ms) var(--wave-ease-enter);
  will-change: opacity, transform;
}

.wave-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .wave-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

/* ==========================================================================
   01 · Hero — the wordmark (signature moment)
   ========================================================================== */

.wave-hero {
  position: relative;
  z-index: 2;
  max-width: 92ch;
  margin-inline: auto;
  padding:
    clamp(80px, 18vh, 160px) var(--wave-s-pad)
    clamp(40px, 8vh, 80px);
  border-bottom: 1px solid var(--wave-hairline);
}

.wave-kicker {
  margin: 0 0 var(--wave-s-6);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--wave-dim);
}

/* Display title: tight tracking for Latin, 3-tier soft/phosphor glow.
   The Korean span resets tracking to 0 and glows phosphor. */
.wave-title {
  margin: 0 0 var(--wave-s-5);
  font-size: clamp(3rem, 10vw, 7rem);
  font-weight: 400;
  line-height: 1.02;
  letter-spacing: -0.03em;
  color: var(--wave-soft);
  text-shadow: var(--wave-glow-soft);
}

.wave-title :lang(ko) {
  margin-left: 0.2em;
  font-size: 0.5em;
  letter-spacing: 0;
  color: var(--wave-phosphor);
  text-shadow: var(--wave-glow-phosphor);
}

.wave-tagline {
  margin: 0;
  max-width: 60ch;
  font-size: clamp(0.95rem, 1.8vw, 1.15rem);
  letter-spacing: 0.01em;
  color: var(--wave-amber);
  text-shadow: var(--wave-glow-amber);
}

/* ==========================================================================
   02 · Spectrum — the signature analyzer (SVG bars + peak-hold + ASCII)
   ========================================================================== */

.wave-spectrum-section {
  position: relative;
  z-index: 2;
  padding: var(--wave-s-pad-y) var(--wave-s-pad);
  border-bottom: 1px solid var(--wave-hairline);
}

.wave-secthead {
  margin: 0 0 var(--wave-s-10);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--wave-dim);
}

/* The analyzer frame — recessed panel with a 4-layer shadow stack:
   inset top highlight + ambient contact + key + far diffuse. */
.wave-spectrum {
  position: relative;
  margin: 0 0 var(--wave-s-6);
  padding: var(--wave-s-4) var(--wave-s-4) var(--wave-s-3);
  background: linear-gradient(
    180deg,
    rgba(74, 222, 128, 0.04),
    rgba(6, 9, 6, 0) 70%
  );
  border: 1px solid var(--wave-hairline);
  border-radius: 2px;
  box-shadow:
    inset 0 1px 0 rgba(74, 222, 128, 0.08),
    0 1px 0 rgba(255, 255, 255, 0.03),
    0 12px 32px rgba(0, 0, 0, 0.45),
    0 40px 80px rgba(0, 0, 0, 0.30);
}

.wave-spectrum__svg {
  display: block;
  width: 100%;
  height: clamp(120px, 22vh, 200px);
  overflow: visible;
  /* One rasterized drop-shadow for the whole meter — cheap at 60fps, still
     reads as a phosphor bloom hugging the bars. */
  filter: drop-shadow(0 0 5px rgba(74, 222, 128, 0.45));
}

/* Bars use the userSpaceOnUse gradient defined in the SVG, so only the
   loudest bands reach the amber zone — real LED-meter behaviour. */
.wave-spectrum__bar {
  fill: url(#wave-grad);
}

.wave-spectrum__peak {
  fill: var(--wave-amber);
}

/* The ASCII channel — a secondary text readout under the meter, dimmer,
   the "what the bars say in glyphs" companion strip. */
.wave-spectrum__ascii {
  margin: var(--wave-s-3) 0 0;
  font-family: var(--wave-font-mono);
  font-size: clamp(0.7rem, 1.4vw, 0.95rem);
  line-height: 1;
  letter-spacing: 0.08em;
  white-space: nowrap;
  overflow: hidden;
  color: var(--wave-phosphor);
  text-shadow:
    0 0 2px rgba(74, 222, 128, 0.7),
    0 0 6px rgba(74, 222, 128, 0.35);
}

.wave-spec-meta {
  margin: 0;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--wave-dim);
}

/* ==========================================================================
   03 · Stats — the ledger readout
   ========================================================================== */

.wave-stats {
  position: relative;
  z-index: 2;
  padding: var(--wave-s-pad-y) var(--wave-s-pad);
  border-bottom: 1px solid var(--wave-hairline);
}

.wave-stat-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--wave-s-8) var(--wave-s-6);
  margin: 0;
}

.wave-stat-grid div {
  padding: var(--wave-s-2) 0 var(--wave-s-2) var(--wave-s-5);
  border-left: 1px solid var(--wave-hairline);
  transition:
    transform 200ms var(--wave-ease-state),
    box-shadow 200ms var(--wave-ease-state),
    border-color 200ms var(--wave-ease-state);
}

/* Lift on hover — transform, not color, carries the depth (craft §7). */
.wave-stat-grid div:hover {
  transform: translateY(-2px);
  border-left-color: var(--wave-phosphor);
  box-shadow:
    0 1px 0 rgba(74, 222, 128, 0.10),
    0 8px 24px rgba(0, 0, 0, 0.45),
    0 24px 48px rgba(0, 0, 0, 0.30);
}

.wave-stat-grid dt {
  margin: 0 0 var(--wave-s-2);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--wave-dim);
}

.wave-stat-grid dd {
  margin: 0;
  font-size: clamp(2rem, 5vw, 3rem);
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--wave-soft);
  text-shadow: var(--wave-glow-soft);
}

/* ==========================================================================
   04 · Marquee — the now-playing crawl
   ========================================================================== */

.wave-marquee {
  position: relative;
  z-index: 2;
  padding: var(--wave-s-4) 0;
  overflow: hidden;
  white-space: nowrap;
  border-bottom: 1px solid var(--wave-hairline);
}

.wave-marquee__track {
  display: inline-block;
  padding-left: 100%;
  font-size: 0.85rem;
  letter-spacing: 0.06em;
  color: var(--wave-phosphor);
  text-shadow:
    0 0 2px rgba(74, 222, 128, 0.6),
    0 0 8px rgba(74, 222, 128, 0.3);
  animation: wave-marquee 40s linear infinite;
}

@keyframes wave-marquee {
  to {
    transform: translateX(-100%);
  }
}

/* ==========================================================================
   05 · Footer — end of transmission
   ========================================================================== */

.wave-foot {
  position: relative;
  z-index: 2;
  max-width: 92ch;
  margin-inline: auto;
  padding:
    clamp(48px, 10vh, 96px) var(--wave-s-pad)
    clamp(64px, 10vh, 120px);
  font-size: 0.8rem;
  color: var(--wave-dim);
}

.wave-foot p {
  margin: 0 0 var(--wave-s-2);
  max-width: 65ch;
}

/* ==========================================================================
   Keyframes — transform / opacity / background-position only
   ========================================================================== */

@keyframes wave-scan {
  from {
    background-position: 0 0;
  }
  to {
    background-position: 0 -3px;
  }
}

/* ==========================================================================
   Media queries — 720 / 900 / 1200
   ========================================================================== */

@media (min-width: 720px) {
  .wave-stat-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--wave-s-10) var(--wave-s-8);
  }

  .wave-secthead {
    font-size: 1.05rem;
  }
}

@media (min-width: 900px) {
  .wave-stat-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--wave-s-8);
  }

  /* Optical breathing room for the hero on wider screens. */
  .wave-hero {
    padding-top: clamp(96px, 20vh, 180px);
  }
}

@media (min-width: 1200px) {
  .wave-hero,
  .wave-spectrum-section,
  .wave-stats,
  .wave-foot {
    max-width: 1200px;
    margin-inline: auto;
  }

  .wave-spectrum__svg {
    height: clamp(160px, 24vh, 220px);
  }
}

/* ==========================================================================
   Reduced motion — instant everything, one beautiful static frame
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .wave-root::after {
    opacity: 0.4;
  }

  .wave-root.wave-js::after {
    animation: none;
  }

  .wave-marquee__track {
    animation: none;
    padding-left: 0;
  }
}
